function unlinkValue(head: ListNode | null, target: number): ListNode | null {
  const nodes: ListNode[] = [];
  for (let n = head; n; n = n.next) nodes.push(n);
  let rest: ListNode | null = null;
  for (let i = nodes.length - 1; i >= 0; i--) {
    if (nodes[i].val !== target) { nodes[i].next = rest; rest = nodes[i]; }
  }
  return rest;
}

