class Solution:
    def unlinkValue(self, head: Optional[ListNode], target: int) -> Optional[ListNode]:
        # build from the back: each kept node points at the cleaned rest
        nodes = []
        while head:
            nodes.append(head)
            head = head.next
        rest = None
        for node in reversed(nodes):
            if node.val != target:
                node.next = rest
                rest = node
        return rest

