function unlinkValue(head: ListNode | null, target: number): ListNode | null {
  const dummy = new ListNode(0, head);
  let cur = dummy;
  while (cur.next) {
    if (cur.next.val === target) cur.next = cur.next.next;
    else cur = cur.next;
  }
  return dummy.next;
}

